std::vector<DiscoveryWorkbenchPart> request(const std::string& operation,const std::string& source_kind,const std::string& model_kind,const std::string& source,const std::string& model,const std::optional<std::string>& options=std::nullopt,const std::optional<std::string>& variant=std::nullopt,const std::string& call_form="with_options"){
 std::vector<DiscoveryWorkbenchPart> parts{{"operation","",operation,false},{"model_kind","",model_kind,false},{"call_form","",call_form,false},{"model_file","model.json",model,true}};
 if(operation!="evaluate_simplicity"){parts.push_back({"source_kind","",source_kind,false});parts.push_back({"source_file","source.json",source,true});}
 if(options)parts.push_back({"options_json","options.json",*options,true});if(variant)parts.push_back({"variant","",*variant,false});return parts;
}
std::map<std::string,std::string> success(const QualityWorkbenchResponse& response){
 assert(response.status==200);const auto root=fields(response.json);assert(root.size()==24&&root.at("family")==word("ORIGINAL_QUALITY_WORKBENCH")&&root.at("version")==word("original-quality-workbench-v1"));assert(root.at("error")=="null"&&root.at("executed")=="true"&&root.at("native_entered")=="true"&&root.at("native_returned")=="true");
 const auto context=fields(root.at("input_context"));assert(context.at("size_t_bytes")==std::to_string(sizeof(std::size_t))&&context.at("int_bytes")==std::to_string(sizeof(int))&&context.at("model_unchanged")=="true");
 const auto input=fields(root.at("input"));assert(input.at("before")==input.at("after"));const auto before=fields(input.at("before")),after=fields(input.at("after"));const auto artifacts=fields(root.at("artifact_bytes"));assert(artifacts.size()==8&&bytes(artifacts.at("full_result_json"))==root.at("result"));
 for(const auto& [role,key]:std::vector<std::pair<std::string,std::string>>{{"source","source_input_json"},{"model","model_input_json"}}){if(before.at(role)=="null")assert(artifacts.at(key)=="null");else assert(bytes(artifacts.at(key))==before.at(role));}
 for(const auto& [role,key]:std::vector<std::pair<std::string,std::string>>{{"source","source_after_json"},{"model","model_after_json"}}){if(after.at(role)=="null")assert(artifacts.at(key)=="null");else assert(bytes(artifacts.at(key))==after.at(role));}
 if(root.at("configured_options")!="null"){assert(bytes(artifacts.at("configured_options_json"))==root.at("configured_options")&&context.at("options_unchanged")=="true");}else assert(artifacts.at("configured_options_json")=="null"&&context.at("options_unchanged")=="null");
 std::size_t primary=0;for(const auto& value:elements(root.at("native_calls"))){const auto call=fields(value);assert(call.at("returned")=="true"&&call.at("error")=="null");if(call.at("stage")==word("primary"))++primary;else assert(call.at("stage")==word("preparation"));}assert(primary==1);return root;
}
std::string result_value(const std::map<std::string,std::string>& root){return fields(root.at("result")).at("value");}
void fail(const QualityWorkbenchResponse& response,const std::string& phase,bool entered){assert(response.status==400);const auto root=fields(response.json);assert(root.at("native_entered")==std::string(entered?"true":"false")&&root.at("native_returned")=="false"&&root.at("executed")=="false"&&root.at("result")=="null");assert(fields(root.at("error")).at("phase")==word(phase));if(entered)assert(fields(root.at("input")).at("before")==fields(root.at("input")).at("after"));}

template<class S,class M>std::string expected(int family,const S& source,const M& model,bool defaults){
 if(family==4)return serialize_quality_workbench_result_json(evaluate_composite(source,model,{}));
 if constexpr(std::is_same_v<M,PnmlDocument>&&(!std::is_same_v<S,EventLog>&&!std::is_same_v<S,EventDataView>)){throw std::logic_error("not a declared combination");}
 else{
  if(family==0){if constexpr(std::is_same_v<S,EventLog>&&!std::is_same_v<M,PnmlDocument>)if(defaults)return serialize_quality_workbench_result_json(evaluate_replay_fitness(source,model,ReplayFitnessVariant::TOKEN_BASED));return serialize_quality_workbench_result_json(evaluate_replay_fitness(source,model,ReplayFitnessVariant::TOKEN_BASED,{}));}
  if(family==1){if constexpr(std::is_same_v<S,EventLog>&&!std::is_same_v<M,PnmlDocument>)if(defaults)return serialize_quality_workbench_result_json(evaluate_precision(source,model,PrecisionVariant::ETCONFORMANCE_TOKEN));return serialize_quality_workbench_result_json(evaluate_precision(source,model,PrecisionVariant::ETCONFORMANCE_TOKEN,{}));}
  if(family==2){if constexpr(std::is_same_v<S,EventLog>&&!std::is_same_v<M,PnmlDocument>)if(defaults)return serialize_quality_workbench_result_json(evaluate_generalization(source,model,GeneralizationVariant::GENERALIZATION_TOKEN));return serialize_quality_workbench_result_json(evaluate_generalization(source,model,GeneralizationVariant::GENERALIZATION_TOKEN,{}));}
 }
 throw std::logic_error("unknown expected family");
}
void all_overloads_and_artifact_reopening(){
 const auto log=sample();const auto flat=stream();const auto tab=table();const auto lazy=LazyEventTable::from_table(tab);const auto petri=net();const auto pt=tree();const auto pnml=document();std::size_t calls=0;
 const std::array<std::string,5> operations={"evaluate_replay_fitness","evaluate_precision","evaluate_generalization","evaluate_simplicity","evaluate_composite"};
 const auto oracle=[&](int family,const std::string& kind,const auto& model,bool defaults){if(kind=="log")return expected(family,log,model,defaults);if(kind=="stream")return expected(family,flat,model,defaults);if(kind=="table")return expected(family,tab,model,defaults);if(kind=="lazy")return expected(family,lazy,model,defaults);if(kind=="view_log")return expected(family,EventDataView(log),model,defaults);if(kind=="view_stream")return expected(family,EventDataView(flat),model,defaults);if(kind=="view_table")return expected(family,EventDataView(tab),model,defaults);return expected(family,EventDataView(lazy),model,defaults);};
 for(int family=0;family<5;++family){if(family==3)continue;for(const auto& model_kind:std::vector<std::string>{"petri_net","process_tree","pnml_document"})for(const auto& kind:std::vector<std::string>{"log","stream","table","lazy","view_log","view_stream","view_table","view_lazy"}){
  const bool document_kind=model_kind=="pnml_document";if(document_kind&&family!=4&&(kind=="stream"||kind=="table"||kind=="lazy"))continue;
  const auto source=kind=="log"||kind=="view_log"?serialize_embedding_workbench_raw_log_json(log):kind=="stream"||kind=="view_stream"?serialize_quality_workbench_stream_json(flat):kind=="lazy"||kind=="view_lazy"?"{\"table\":"+serialize_quality_workbench_table_json(tab)+",\"valid\":true,\"row_count\":2}":serialize_quality_workbench_table_json(tab);
  const auto model=model_kind=="petri_net"?serialize_oc_playout_workbench_petri_net_json(petri):model_kind=="process_tree"?serialize_quality_workbench_tree_json(pt):serialize_quality_workbench_document_json(pnml);
  for(bool defaults:{false,true}){if(defaults&&(family>2||kind!="log"||document_kind))continue;const auto variant=family==4?std::nullopt:std::make_optional(family==0?"TOKEN_BASED":family==1?"ETCONFORMANCE_TOKEN":"GENERALIZATION_TOKEN");auto parts=request(operations[family],kind,model_kind,source,model,defaults?std::nullopt:std::make_optional(std::string("{}")),variant,defaults?"default_options":"with_options");const auto root=success(execute_quality_workbench(parts));const auto exact=model_kind=="petri_net"?oracle(family,kind,petri,defaults):model_kind=="process_tree"?oracle(family,kind,pt,defaults):oracle(family,kind,pnml,defaults);assert(result_value(root)==exact);const auto context=fields(root.at("input_context"));assert(context.at("source_unchanged")=="true");if(kind=="lazy"||kind=="view_lazy")assert(context.at("lazy_scans")!="[]");else assert(context.at("lazy_scans")=="[]");const auto artifacts=fields(root.at("artifact_bytes"));
   // Reopen the actual canonical Files, not a reconstructed source/model.
   for(auto& part:parts){if(part.name=="source_file")part.bytes=bytes(artifacts.at("source_input_json"));if(part.name=="model_file")part.bytes=bytes(artifacts.at("model_input_json"));if(part.name=="options_json")part.bytes=bytes(artifacts.at("configured_options_json"));}const auto again=success(execute_quality_workbench(parts));assert(result_value(again)==exact);++calls;
  }
 }}
 const auto shown=presentation();for(const auto& model_kind:std::vector<std::string>{"petri_net","process_tree","pnml_document","presentation"}){const auto model=model_kind=="petri_net"?serialize_oc_playout_workbench_petri_net_json(petri):model_kind=="process_tree"?serialize_quality_workbench_tree_json(pt):model_kind=="pnml_document"?serialize_quality_workbench_document_json(pnml):serialize_quality_workbench_presentation_json(shown);const auto root=success(execute_quality_workbench(request(operations[3],"",model_kind,"",model)));const auto exact=model_kind=="petri_net"?serialize_quality_workbench_result_json(evaluate_simplicity(petri)):model_kind=="process_tree"?serialize_quality_workbench_result_json(evaluate_simplicity(pt)):model_kind=="pnml_document"?serialize_quality_workbench_result_json(evaluate_simplicity(pnml)):serialize_quality_workbench_result_json(evaluate_simplicity(shown));assert(result_value(root)==exact&&root.at("source_kind")=="null");++calls;}
 assert(calls==97);
}

