void table_private_metadata_and_exact_raw_handoffs(){
 // Explicit complete raw bytes ensure no earlier inspection writer can drop
 // metadata before this regression reaches the selected route.
 const std::string submitted=R"({"native_byte_strings":"hex-v1","native_schema":"event-table-raw-v1","value":{"columns":["636173653a636f6e636570743a6e616d65","636f6e636570743a6e616d65"],"rows":[[{"key":"636173653a636f6e636570743a6e616d65","value":"63"},{"key":"636f6e636570743a6e616d65","value":"41"}]],"attributes":[],"metadata":{"extensions":[],"classifiers":[],"trace_globals":[],"event_globals":[],"properties":[],"globals":[],"compatibility_snapshot_valid":true,"compatibility_globals_snapshot":[{"scope":"6c6174656e74","attributes":[{"key":"6f6c64","value":"676c6f62616c"}]}],"compatibility_trace_globals_snapshot":[{"key":"7467","value":"6f6c64"}],"compatibility_event_globals_snapshot":[{"key":"6567","value":"6f6c64"}]},"dtypes":[],"index":null,"categorical_dtypes":[]}})";
 const auto original=parse_embedding_workbench_table_json(submitted);assert(original.metadata.compatibility_snapshot_valid&&original.metadata.compatibility_globals_snapshot[0].scope=="latent"&&original.metadata.compatibility_trace_globals_snapshot[0].key=="tg"&&original.metadata.compatibility_event_globals_snapshot[0].key=="eg");
 const auto canonical=serialize_quality_workbench_table_json(original);const auto full=fields(fields(canonical).at("value"));assert(full.size()==7&&fields(full.at("metadata")).size()==10);
 const auto exact=serialize_quality_workbench_result_json(evaluate_generalization(original,net()));
 for(const auto& kind:std::vector<std::string>{"table","view_table","lazy","view_lazy"}){
  const bool lazy=kind=="lazy"||kind=="view_lazy";const auto body=lazy?"{\"table\":"+submitted+",\"valid\":true,\"row_count\":1}":submitted;
  auto parts=request("evaluate_generalization",kind,"petri_net",body,serialize_oc_playout_workbench_petri_net_json(net()));const auto root=success(execute_quality_workbench(parts));assert(result_value(root)==exact);const auto input=fields(root.at("input"));const auto before=fields(input.at("before")).at("source"),after=fields(input.at("after")).at("source");assert(before==after);const auto raw=lazy?fields(before).at("table"):before;assert(raw==canonical);const auto restored=parse_embedding_workbench_table_json(raw);assert(restored.metadata.compatibility_snapshot_valid&&restored.metadata.compatibility_globals_snapshot[0].scope=="latent"&&restored.metadata.compatibility_globals_snapshot[0].attributes[0].value=="global"&&restored.metadata.compatibility_trace_globals_snapshot[0].key=="tg"&&restored.metadata.compatibility_event_globals_snapshot[0].key=="eg");
  const auto artifacts=fields(root.at("artifact_bytes"));for(auto& part:parts)if(part.name=="source_file")part.bytes=bytes(artifacts.at("source_input_json"));const auto again=success(execute_quality_workbench(parts));assert(fields(fields(again.at("input")).at("before")).at("source")==before&&result_value(again)==exact);
 }
 // Raw index alternatives are flattened {index,value}; recursive tuples,
 // category attributes, missing cells and literal bytes remain constructor
 // storage even when their dimensions would fail a later native consumer.
 auto stored=original;const auto all=all_bytes();stored.columns={all,all};stored.dtypes={all};stored.rows[0][0]=std::nullopt;stored.rows[0][1]->is_null=true;stored.rows[0][1]->typed_value=NativeDate{all,static_cast<NativeDateResolution>(-9),all};EventTableIndexLabel leaf{EventAttribute{all,all}};EventTableIndexLabel tuple{std::vector<EventTableIndexLabel>{leaf,EventTableIndexLabel{std::vector<EventTableIndexLabel>{leaf}}}};stored.index=EventTableIndex{};stored.index->kind=all;stored.index->dtype=all;stored.index->names={all,std::nullopt,""};stored.index->labels={tuple};stored.categorical_dtypes={EventTableCategoricalDtype{all,{EventAttribute{all,all}},true},std::nullopt};const auto raw=serialize_quality_workbench_table_json(stored);const auto copy=parse_embedding_workbench_table_json(raw);assert(serialize_quality_workbench_table_json(copy)==raw&&copy.columns[0]==all&&copy.index->kind==all&&copy.index->labels.size()==1&&copy.categorical_dtypes[0]->categories_dtype==all&&std::get<NativeDate>(copy.rows[0][1]->typed_value).timezone==all);const auto labels=elements(fields(fields(fields(raw).at("value")).at("index")).at("labels"));assert(fields(labels[0]).size()==2&&fields(labels[0]).contains("index")&&fields(labels[0]).contains("value"));
}

